const event = $json.body || $json;
const body = event.payload || event;
const headers = $json.headers || {};
const signaturePresent = Boolean(headers['x-nlcare-signature'] || headers['X-NLCare-Signature']);
const timestampPresent = Boolean(headers['x-nlcare-timestamp'] || headers['X-NLCare-Timestamp']);
const required = ["alert_id", "event_type", "priority", "review_path", "delivery_scope", "recipient_scope"];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
const blocked = ["patient_name", "patient_id", "raw_patient_message", "full_chat_transcript", "medical_record_number", "date_of_birth", "address", "phone", "email", "raw_prompt", "raw_response", "raw_trace", "private_chain_of_thought", "genetic_variant_details_for_patient_advice"];
const blockedPresent = blocked.filter((key) => body[key] !== undefined);
const boundaryOk = event.phi_allowed === false && event.clinical_validation === false;
return [{ json: { ok: signaturePresent && timestampPresent && boundaryOk && missing.length === 0 && blockedPresent.length === 0, signaturePresent, timestampPresent, boundaryOk, missing, blockedPresent, body } }];
